<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {api} from '../api';import {useWorkspace,type WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const data=ref<any>(null),query=ref(''),inactive=ref(false),error=ref(''),loading=ref(false);
async function load(){if(loading.value)return;loading.value=true;error.value='';try{data.value=await api('stores?inactive='+inactive.value);}catch(e){data.value=null;error.value=(e as Error).message;}finally{loading.value=false;}}
const rows=computed(()=>(data.value?.stores||[]).filter((s:any)=>[s.store_code,s.store_name,s.short_name,s.hr_store_code,s.manager_name,s.address,s.phone,...s.managers.map((m:any)=>m.name)].join(' ').toLowerCase().includes(query.value.toLowerCase())));
const maps=(s:any)=>s.gps_latitude!=null&&s.gps_longitude!=null?`https://www.google.com/maps?q=${s.gps_latitude},${s.gps_longitude}`:s.address?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address)}`:'';
function open(kind:'store-editor'|'store-relocation'|'store-employees'|'store-personnel'|'store-promotions',s?:any){const tab=work.open(kind,s?.id||'',s?.id);tab.title=s?(kind==='store-editor'?'編輯門市':kind==='store-promotions'?'批次升遷':kind==='store-personnel'?'門市員工主檔':kind==='store-employees'?'門市員工':'搬遷沿革')+' · '+s.store_name:'新增門市';}
onMounted(load);watch(()=>work.active,id=>{if(id===props.tab.id)load();});
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市管理</p><h1>門市管理</h1><p class="muted">門市主檔、營運狀態與搬遷沿革。</p></div><div class="module-actions"><button v-if="data?.capabilities.map" @click="work.open('store-map')">門市整合地圖</button><button v-if="data?.capabilities.create" class="primary" @click="open('store-editor')">新增門市</button><button :disabled="loading" @click="load">重新整理</button></div></header><p v-if="error" role="alert" class="notice error">{{error}}</p><div class="store-filters"><label>搜尋門市<input v-model="query" placeholder="代碼、名稱、負責人、地址或電話"></label><label v-if="data?.capabilities.inactive" class="check-filter"><input type="checkbox" v-model="inactive" :disabled="loading" @change="load">顯示已停止門市<template v-if="data.inactiveCount!=null"> ({{data.inactiveCount}})</template></label></div><p v-if="loading" role="status">載入門市資料…</p><template v-else-if="data"><p class="muted">{{rows.length}} 間門市<template v-if="data.inactiveCount!=null">（已停止 {{data.inactiveCount}} 間{{inactive?'，目前已顯示':'，目前隱藏'}}）</template>；員工數依各店最新人員月份計算，排除離職。</p><div class="module-table"><table><thead><tr><th>門市</th><th>負責人／管理者</th><th>地址／電話</th><th>員工</th><th>營運狀態</th><th>操作</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{s.store_code}}<br><strong>{{s.store_name}}</strong><br>{{s.short_name||'—'}}<p v-if="s.is_franchise">加盟店</p><small v-if="s.hr_store_code">人資代碼 {{s.hr_store_code}}</small></td><td>{{s.manager_name||'未指定負責人'}}<p class="muted">{{s.managers.map((m:any)=>m.name).join('、')}}</p></td><td><p>{{s.address||'未提供地址'}}</p><p>{{s.phone||'未提供電話'}}</p><a v-if="maps(s)" :href="maps(s)" target="_blank" rel="noopener noreferrer">Google Maps ↗</a></td><td>{{s.employee_count}} 人<br><small>{{s.latest_month||'尚無月份資料'}}</small></td><td>{{s.is_active?'營運中':'已停止'}}</td><td><div class="module-actions"><button @click="open('store-employees',s)">員工</button><button v-if="data.capabilities.promotions && s.is_active" @click="open('store-promotions',s)">批次升遷</button><button v-if="data.capabilities.personnel" @click="open('store-personnel',s)">員工主檔／歷程</button><button v-if="data.capabilities.edit" @click="open('store-editor',s)">編輯</button><button v-if="data.capabilities.relocate" @click="open('store-relocation',s)">{{s.is_active?'搬遷／沿革':'查看沿革'}}</button></div></td></tr><tr v-if="!rows.length"><td colspan="6">{{query?'沒有符合條件的門市':'尚無可查看的門市'}}</td></tr></tbody></table></div></template></template><style scoped>.store-filters{display:flex;gap:20px;flex-wrap:wrap;align-items:end}.store-filters label{display:grid;gap:8px;min-width:260px}.store-filters .check-filter{display:flex;align-items:center;min-width:0;padding:10px}.check-filter input{min-width:18px;min-height:18px;width:18px;height:18px}.module-table td{max-width:300px;white-space:normal;overflow-wrap:anywhere}.module-table a{text-decoration:underline}</style>
